patch:
diff --git a/repro/no-unused-expressions-use-strict.js b/repro/no-unused-expressions-use-strict.js
new file mode 100644
index 0000000..3b6df8c
--- /dev/null
+++ b/repro/no-unused-expressions-use-strict.js
@@ -0,0 +1,38 @@
+/**
+ * @fileoverview Check: `no-unused-expressions` must not report a `'use strict'`
+ * directive. The reported failure is from core-js, whose `packages/core-js`
+ * sources are linted with `ecmaVersion: 3` and the options below.
+ *
+ * Run from the repo root: node repro/no-unused-expressions-use-strict.js
+ * Exits 1 while the bug is present, 0 once the directive is no longer reported.
+ */
+"use strict";
+
+const { Linter } = require("../lib/api");
+
+const code = "'use strict';\nvar parent = require('../stable/aggregate-error');\n";
+
+const messages = new Linter().verify(code, {
+	languageOptions: { ecmaVersion: 3, sourceType: "script" },
+	rules: {
+		"no-unused-expressions": [
+			"error",
+			{
+				allowShortCircuit: true,
+				allowTernary: true,
+				allowTaggedTemplates: true,
+			},
+		],
+	},
+});
+
+if (messages.length === 0) {
+	console.log("OK: no problems reported for 'use strict'");
+	process.exit(0);
+}
+
+console.error("FAIL: expected no problems for 'use strict', got:");
+for (const m of messages) {
+	console.error(`  ${m.line}:${m.column} ${m.ruleId}: ${m.message}`);
+}
+process.exit(1);
